package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** A person on a sheet, with a name and a dated grade (A, B or C). */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The first grade the person was given: in force from the beginning of time until a later one. */
    @Column(name = "grade", nullable = false)
    private String grade;

    /** The grades recorded since, by the date each is in force from. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    @MapKeyColumn(name = "from_date")
    @Column(name = "grade", nullable = false)
    private Map<LocalDate, String> datedGrades = new HashMap<>();

    /** The date the person is retired from; null while not retired. Set, they count as retired
     *  at once, whatever the date. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Whether the person is on hold: their OPEN claims then count in no live total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** Raised on every save, so an edit of a version someone else has since saved is refused. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grade = grade;
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** A grade and the date it is in force from (null: from the beginning of time). */
    public record DatedGrade(String grade, LocalDate from) {
    }

    /** The grade in force on a date: the one with the latest from-date on or before it, else the first. */
    public String gradeOn(LocalDate on) {
        Map.Entry<LocalDate, String> latest = new TreeMap<>(datedGrades).floorEntry(on);
        return latest == null ? grade : latest.getValue();
    }

    /** Record a grade from a date, in place of any recorded from the same date. */
    public void recordGrade(String grade, LocalDate from) {
        datedGrades.put(from, grade);
    }

    /** Every grade the person has been given, by from-date, the first one (undated) leading. */
    public List<DatedGrade> getGrades() {
        List<DatedGrade> out = new ArrayList<>();
        out.add(new DatedGrade(grade, null));
        new TreeMap<>(datedGrades).forEach((from, g) -> out.add(new DatedGrade(g, from)));
        return out;
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    public boolean isRetired() {
        return retiredFrom != null;
    }

    /** Whether a claim dated {@code date} is refused for the person: one after their retirement date. */
    public boolean retiredBefore(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.session.CurrentUser;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets/{sheetId}/people")
@Validated
public class PersonController {

    /** A person as the screen shows them, with their statement count and their last statement's
     *  due-total (two decimals; null when it was n/a or they have none) and date, and the date
     *  they are retired from (null while not retired), whether they are on hold, and the ids of
     *  their patrons in the order they were named. The grade is the one in force on the sheet's
     *  today; grades lists every grade they have been given, by from-date, the first one undated. */
    public record PersonView(long id, String name, String grade, long version, int statementCount,
            String statedTotal, LocalDate statementDate, LocalDate retiredFrom, boolean held, List<Long> patronIds,
            List<Person.DatedGrade> grades) {
        public static PersonView of(Person p, LocalDate today, StatementSummary s, List<Long> patronIds) {
            return new PersonView(p.getId(), p.getName(), p.gradeOn(today), p.getVersion(), s.count(),
                    s.lastDueTotal() == null ? null : s.lastDueTotal().setScale(2).toPlainString(), s.lastDate(),
                    p.getRetiredFrom(), p.isHeld(), patronIds, p.getGrades());
        }
    }

    /** A person's values as the form submits them; the name is stored with surrounding spaces removed.
     *  An edit carries the version of the person its editor loaded, and the date its grade is in
     *  force from (null: the sheet's today); an add's grade is in force from the beginning of time. */
    public record PersonForm(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            Long version,
            LocalDate gradeFrom) {
    }

    /** A retirement as the row submits it; a missing date takes the sheet's today. */
    public record RetireForm(LocalDate from) {
    }

    /** A hold as the row submits it: true puts the person on hold, false takes them off it. */
    public record HoldForm(@NotNull Boolean held) {
    }

    /** A patron as the row submits it: the id of another person on the sheet. */
    public record PatronForm(@NotNull Long patronId) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        Map<Long, StatementSummary> summaries = service.statementSummaries(sheetId);
        Map<Long, List<Long>> patrons = service.patronIds(sheetId);
        LocalDate today = service.today(sheetId);
        return service.list(sheetId).stream()
                .map(p -> PersonView.of(p, today, summaries.getOrDefault(p.getId(), StatementSummary.NONE),
                        patrons.getOrDefault(p.getId(), List.of())))
                .toList();
    }

    @GetMapping("/{id}")
    public PersonView get(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user) {
        return view(sheetId, service.get(sheetId, id));
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PersonForm body) {
        return view(sheetId, service.add(sheetId, user.trim(), body.name(), body.grade()));
    }

    @PutMapping("/{id}")
    public PersonView update(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PersonForm body) {
        return view(sheetId, service.update(sheetId, user.trim(), id, body.version(), body.name(), body.grade(),
                body.gradeFrom()));
    }

    @PostMapping("/{id}/retire")
    public PersonView retire(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @RequestBody(required = false) RetireForm body) {
        return view(sheetId, service.retire(sheetId, user.trim(), id, body == null ? null : body.from()));
    }

    @PostMapping("/{id}/hold")
    public PersonView hold(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody HoldForm body) {
        return view(sheetId, service.hold(sheetId, user.trim(), id, body.held()));
    }

    @PostMapping("/{id}/patrons")
    public PersonView addPatron(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "\\S+") String sheetId,
            @PathVariable long id,
            @RequestHeader(CurrentUser.HEADER) @NotBlank @Size(max = 100) String user,
